sql.if:
and (p.owner_user_id = #{params.projectAccessUserId}
     or exists (select 1 from review_project_member pm
                where pm.project_id = p.project_id
                  and pm.user_id = #{params.projectAccessUserId}
                  and pm.status = '0'))

mapper.select:
SELECT DATE(closed_time) AS stat_date,
       SUM(CASE WHEN status = 'CLOSED' THEN 1 ELSE 0 END) AS issue_closed,
       SUM(CASE WHEN status = 'FALSE_POSITIVE' THEN 1 ELSE 0 END) AS issue_false_positive
FROM review_issue
WHERE project_id = #{projectId}
  AND closed_time IS NOT NULL
  AND status IN ('CLOSED', 'FALSE_POSITIVE')
  AND DATE(closed_time) >= #{beginDate}
  AND DATE(closed_time) <= #{endDate}
GROUP BY DATE(closed_time)

SELECT DATE(a.create_time) AS stat_date,
       COUNT(1) AS issue_confirmed
FROM review_issue_action a
INNER JOIN review_issue i ON i.issue_id = a.issue_id
WHERE i.project_id = #{projectId}
  AND a.action_type = 'CONFIRM'
  AND DATE(a.create_time) >= #{beginDate}
  AND DATE(a.create_time) <= #{endDate}
GROUP BY DATE(a.create_time)

SELECT DATE(COALESCE(last_attempt_time, create_time)) AS stat_date,
       COUNT(1) AS delivery_total,
       SUM(CASE WHEN delivery_status = 'SUCCESS' THEN 1 ELSE 0 END) AS delivery_success
FROM review_delivery_record
WHERE project_id = #{projectId}
  AND delivery_status IN ('SUCCESS', 'FAILED', 'MANUAL', 'SKIPPED')
  AND DATE(COALESCE(last_attempt_time, create_time)) >= #{beginDate}
  AND DATE(COALESCE(last_attempt_time, create_time)) <= #{endDate}
GROUP BY DATE(COALESCE(last_attempt_time, create_time))

SELECT DATE(COALESCE(process_time, receive_time)) AS stat_date,
       SUM(CASE WHEN process_status = 'ACCEPTED' THEN 1 ELSE 0 END) AS event_accepted,
       SUM(CASE WHEN process_status = 'IGNORED' THEN 1 ELSE 0 END) AS event_ignored
FROM review_webhook_event
WHERE project_id = #{projectId}
  AND process_status IN ('ACCEPTED', 'IGNORED')
  AND DATE(COALESCE(process_time, receive_time)) >= #{beginDate}
  AND DATE(COALESCE(process_time, receive_time)) <= #{endDate}
GROUP BY DATE(COALESCE(process_time, receive_time))

SELECT DATE(t.finished_time) AS stat_date,
       COUNT(DISTINCT t.task_id) AS task_covered
FROM review_task t
INNER JOIN review_delivery_record d ON d.task_id = t.task_id AND d.delivery_status = 'SUCCESS'
WHERE t.project_id = #{projectId}
  AND t.task_status = 'SUCCESS'
  AND t.finished_time IS NOT NULL
  AND DATE(t.finished_time) >= #{beginDate}
  AND DATE(t.finished_time) <= #{endDate}
GROUP BY DATE(t.finished_time)

SELECT COUNT(1)
FROM review_issue i
INNER JOIN review_project p ON p.project_id = i.project_id
INNER JOIN sys_business_system bs ON bs.system_id = p.business_system_id
INNER JOIN sys_dept d ON d.dept_id = p.dept_id
INNER JOIN sys_user owner ON owner.user_id = p.owner_user_id
WHERE i.severity IN ('CRITICAL', 'HIGH')
  AND i.status IN ('AWAITING_CONFIRM', 'AWAITING_FIX', 'RECHECKING')

    AND p.business_system_id = #{params.businessSystemId}


    AND i.project_id = #{projectId}


    AND i.project_id IN

        #{pid}


${params.dataScope}

SELECT COALESCE(NULLIF(TRIM(i.category), ''), '未分类') AS category, COUNT(1) AS cnt FROM review_issue i INNER JOIN review_project p ON p.project_id = i.project_id INNER JOIN sys_business_system bs ON bs.system_id = p.business_system_id INNER JOIN sys_dept d ON d.dept_id = p.dept_id INNER JOIN sys_user owner ON owner.user_id = p.owner_user_id WHERE i.origin = 'NEW' AND i.create_time IS NOT NULL AND DATE(i.create_time) >= #{params.beginDate} AND DATE(i.create_time) <= #{params.endDate}
AND p.business_system_id = #{params.businessSystemId}
AND i.project_id = #{projectId}
${params.dataScope}
GROUP BY COALESCE(NULLIF(TRIM(i.category), ''), '未分类') ORDER BY cnt DESC LIMIT 20

SELECT dr.channel AS channel,
       COUNT(1) AS delivery_total,
       SUM(CASE WHEN dr.delivery_status = 'SUCCESS' THEN 1 ELSE 0 END) AS delivery_success
FROM review_delivery_record dr
INNER JOIN review_project p ON p.project_id = dr.project_id
INNER JOIN sys_business_system bs ON bs.system_id = p.business_system_id
INNER JOIN sys_dept d ON d.dept_id = p.dept_id
INNER JOIN sys_user owner ON owner.user_id = p.owner_user_id
WHERE dr.delivery_status IN ('SUCCESS', 'FAILED', 'MANUAL', 'SKIPPED')
  AND DATE(COALESCE(dr.last_attempt_time, dr.create_time)) >= #{params.beginDate}
  AND DATE(COALESCE(dr.last_attempt_time, dr.create_time)) <= #{params.endDate}

    AND p.business_system_id = #{params.businessSystemId}


    AND dr.project_id = #{projectId}

${params.dataScope}

GROUP BY dr.channel
ORDER BY delivery_total DESC

SELECT i.title AS title, i.severity AS severity, t.pr_author AS author_key, COUNT(1) AS cnt FROM review_issue i INNER JOIN review_task t ON t.task_id = i.last_task_id WHERE i.status IN ('AWAITING_CONFIRM', 'AWAITING_FIX', 'RECHECKING') AND t.pr_author IN
#{k}
GROUP BY i.title, i.severity, t.pr_author ORDER BY cnt DESC LIMIT #{limit}
